export function enablePageSwipe(routes){const main=document.querySelector('#app'),footer=document.querySelector('#mobile-navigation');let start=null,moved=false;const surfaces=[main,footer];for(const surface of surfaces){surface.style.touchAction='pan-y';surface.addEventListener('pointerdown',e=>{if(document.body.classList.contains('login-screen')||e.button!==0||e.target.closest('input,textarea,select,[data-no-swipe]'))return;start={id:e.pointerId,x:e.clientX,y:e.clientY};moved=false});surface.addEventListener('pointermove',e=>{if(!start||e.pointerId!==start.id)return;const x=e.clientX-start.x,y=e.clientY-start.y;if(Math.abs(x)>16&&Math.abs(x)>Math.abs(y)*1.4)moved=true});surface.addEventListener('pointerup',e=>{if(!start||e.pointerId!==start.id)return;const x=e.clientX-start.x,y=e.clientY-start.y;start=null;if(Math.abs(x)<55||Math.abs(x)<Math.abs(y)*1.4)return;const route=location.hash.slice(1)||'home',i=routes.indexOf(route);if(i<0)return;const next=i+(x<0?1:-1);if(next>=0&&next<routes.length){location.hash=routes[next];moved=true}});surface.addEventListener('pointercancel',()=>{start=null;moved=false});surface.addEventListener('click',e=>{if(moved){e.preventDefault();e.stopImmediatePropagation();moved=false}},true)}}
